"use client";
import { useCallback, useEffect, useRef, useState } from "react";
import { Download, Maximize2, ShieldCheck, X } from "lucide-react";
import { api } from "../lib/api";
import { Button } from "./ui/Button";
import { Alert, Spinner } from "./ui/Feedback";
import { Card } from "./ui/Brand";

type QrData = { qr_code_image: string; qr_payload: string; collaborator_code: string; collaborator_name: string; verified: boolean };

/**
 * The Partner's own referral QR. The QR content is the canonical Partner code (the same payload Merchants scan via POST /qr/resolve),
 * generated by the backend from the CURRENT code on every request, so Partners whose duplicate V1 code was remapped only ever see their new unique code.
 * Scanning never creates a transaction, payment or commission.
 */
export function PartnerQrCard({ verified }: { verified: boolean }) {
  const [data, setData] = useState<QrData | null>(null);
  const [error, setError] = useState(false);
  const [attempt, setAttempt] = useState(0);
  const dialog = useRef<HTMLDialogElement>(null);

  useEffect(() => {
    if (!verified) return;
    let active = true;
    setError(false);
    api.get("/collaborators/me/qr-code").then((d) => active && setData(d)).catch(() => active && setError(true));
    return () => { active = false; };
  }, [verified, attempt]);

  const download = useCallback(() => {
    if (!data) return;
    const link = document.createElement("a");
    link.href = data.qr_code_image;
    link.download = `VNO-QR-${data.collaborator_code}.png`;
    document.body.appendChild(link); link.click(); link.remove();
  }, [data]);

  if (!verified) {
    return <Card className="p-5" data-testid="partner-qr-locked"><Alert tone="info" title="Mã QR sẽ sẵn sàng sau khi hồ sơ được duyệt">Quản trị viên cần xác minh tài khoản Đối tác trước khi mã QR giới thiệu được cấp.</Alert></Card>;
  }

  return (
    <Card className="overflow-hidden" data-testid="partner-qr-card">
      <div className="grid gap-5 p-5 sm:grid-cols-[auto_1fr] sm:items-center">
        <div className="mx-auto">
          {data
            ? <button type="button" onClick={() => dialog.current?.showModal()} aria-label="Phóng to mã QR" className="group relative block rounded-card border border-line bg-white p-3">
                {/* eslint-disable-next-line @next/next/no-img-element -- data: URL generated by the API */}
                <img src={data.qr_code_image} alt={`Mã QR của Đối tác ${data.collaborator_code}`} data-testid="partner-qr-image" className="size-56 sm:size-60" />
                <span className="absolute right-2 top-2 grid size-9 place-items-center rounded-full bg-ink/80 text-white opacity-90"><Maximize2 aria-hidden="true" className="size-4" /></span>
              </button>
            : error
              ? <div className="grid size-56 place-items-center"><Alert tone="danger" title="Không tải được mã QR" action={<Button variant="secondary" onClick={() => setAttempt((n) => n + 1)}>Thử lại</Button>} /></div>
              : <div className="grid size-56 place-items-center"><Spinner label="Đang tạo mã QR…" /></div>}
        </div>
        <div className="min-w-0 text-center sm:text-left">
          <p className="inline-flex items-center gap-1 text-xs font-semibold text-success-700"><ShieldCheck aria-hidden="true" className="size-4" />Đã xác minh</p>
          <h2 className="mt-1 text-xl font-bold">Mã QR giới thiệu của bạn</h2>
          <p className="mt-1 text-sm text-ink-muted">Mã đối tác</p>
          <p className="font-mono text-2xl font-bold tracking-wide" data-testid="partner-qr-code">{data?.collaborator_code ?? "…"}</p>
          <p className="mt-2 text-sm text-ink-muted">Đưa mã này cho nhà cung cấp quét để ghi nhận bạn là người giới thiệu. Quét mã không tự tạo giao dịch, thanh toán hay hoa hồng.</p>
          <div className="mt-4 flex flex-wrap justify-center gap-2 sm:justify-start">
            <Button onClick={() => dialog.current?.showModal()} disabled={!data}><Maximize2 aria-hidden="true" className="size-4" />Phóng to</Button>
            <Button variant="secondary" onClick={download} disabled={!data} data-testid="partner-qr-download"><Download aria-hidden="true" className="size-4" />Tải xuống PNG</Button>
          </div>
        </div>
      </div>

      <dialog ref={dialog} aria-label="Mã QR phóng to" onClick={(e) => { if (e.target === dialog.current) dialog.current?.close(); }} className="m-auto w-[min(92vw,34rem)] rounded-card p-0 backdrop:bg-black/70">
        <div className="flex items-center justify-between border-b border-line p-3">
          <p className="font-mono text-lg font-bold">{data?.collaborator_code}</p>
          <button type="button" onClick={() => dialog.current?.close()} aria-label="Đóng" className="grid size-11 place-items-center rounded-full hover:bg-canvas"><X aria-hidden="true" className="size-5" /></button>
        </div>
        <div className="bg-white p-4">
          {data && (/* eslint-disable-next-line @next/next/no-img-element */
            <img src={data.qr_code_image} alt={`Mã QR phóng to của Đối tác ${data.collaborator_code}`} data-testid="partner-qr-image-large" className="mx-auto aspect-square w-full max-w-[28rem]" />)}
          <p className="mt-2 text-center text-xs text-ink-muted">Tăng độ sáng màn hình khi trình mã cho nhà cung cấp.</p>
        </div>
      </dialog>
    </Card>
  );
}
